import 'package:llama_flutter_android/llama_flutter_android.dart';

final controller = LlamaController();
await controller.loadModel(modelPath: '/path/to/model.gguf', threads: 4, contextSize: 2048);
final sub = controller.generate(prompt: 'Hello', maxTokens: 100).listen((token) => print(token), onDone: () => print('Done'));
await controller.stop();
await controller.dispose();
